    "tone": "academic, data-forward",
    "venue": "The Lancet Digital Health – AI in Clinical Medicine Symposium"
  },
  "brief": {
    "title": "Artificial Intelligence in Clinical Decision-Making: Performance, Safety, and Implementation Gaps",
    "one_liner": "A synthesis of current evidence on AI-assisted clinical decision support systems, highlighting diagnostic accuracy gains, safety considerations, and the translational gap from research to bedside deployment.",
    "goal": "Viewers should understand the current state of AI in clinical decision-making — where it excels, where risks remain, and what steps are needed to bridge the implementation gap in real-world healthcare settings."
  },
  "sections": [
    {
      "id": "background",
      "title": "Background & Motivation",
      "objective": "Establish why AI-based clinical decision support is a critical area of digital health research and frame the scope of the review."
    },
    {
      "id": "diagnostic-performance",
      "title": "Diagnostic Performance of AI Systems",
      "objective": "Present key accuracy and sensitivity metrics comparing AI-assisted versus standard clinical workflows across major disease domains."
    },
    {
      "id": "safety-equity",
      "title": "Safety, Bias, and Health Equity",
      "objective": "Highlight evidence on algorithmic bias, patient safety events, and disparities across demographic groups."
    },
    {
      "id": "implementation-gap",
      "title": "The Translational Implementation Gap",
      "objective": "Quantify how few validated AI tools reach routine clinical use and identify the primary barriers."
    },
    {
      "id": "recommendations",
      "title": "Recommendations & Future Directions",
      "objective": "Summarize actionable steps for researchers, clinicians, and policymakers to accelerate safe AI adoption."
    }
  ],
  "metrics": [
    {
      "label": "AI Diagnostic Sensitivity (median across studies)",
      "value": "87.5%"
    },
    {
      "label": "Clinician-Only Diagnostic Sensitivity (median)",
      "value": "78.2%"
    },
    {
      "label": "Prospective Validation Rate of Published AI Models",
      "value": "<5%"
    },
    {
      "label": "Studies Reporting Demographic Bias Assessment",
      "value": "18%"
    },
    {
      "label": "Reduction in Diagnostic Turnaround Time with AI",
      "value": "32%"
    },
    {
      "label": "Regulatory-Cleared AI/ML Medical Devices (FDA, as of 2023)",
      "value": "692"
    }
  ]
}

